"""Render the original project-history journal and verified ambience links."""
from html import escape
import json,math,re

def creative_pages(root):
    posts=json.loads((root/'content/journal.json').read_text(encoding='utf-8'))
    videos=json.loads((root/'content/relaxation-videos.json').read_text(encoding='utf-8'))
    style=(root/'editorial.css').read_text(encoding='utf-8')
    e=lambda text:escape(str(text),quote=True)
    categories=list(dict.fromkeys(p['category'] for p in posts))
    records=[]
    for i,p in enumerate(posts):
        words=len(' '.join(p['paragraphs']).split())
        body=f'<p class="reading-deck">{e(p["description"])}</p><div class="reading-meta"><span>Note {p["number"]:02} of 52</span><span>{e(p["category"])}</span><span>Origami Penguin</span><span>Published <time datetime="2026-11-04">November 4, 2026</time></span><span>{max(1,math.ceil(words/200))} min read</span></div>'
        body+='<article class="reading-body" aria-label="Article text">'+''.join('<p>'+e(s)+'</p>' for s in p['paragraphs'])+'</article>'
        body+='<div class="reading-actions">'
        body+=('<a href="/'+posts[i-1]['slug']+'">← Previous note<br>'+e(posts[i-1]['title'])+'</a>') if i else '<a href="/blog">← All 52 notes</a>'
        body+=('<a class="next" href="/'+posts[i+1]['slug']+'">Next note →<br>'+e(posts[i+1]['title'])+'</a>') if i+1<len(posts) else '<a class="next" href="/blog">Back to the collection →</a>'
        body+='</div><aside class="series-note"><p>Part of <a href="/blog">The Creative Notebook</a>: a 52-part reading series reflecting on the ongoing work of building Origami Penguin. Read one each week or explore the collection at your own pace.</p><p><a href="/chill-corner">Need a quieter background? Visit Chill Corner.</a></p></aside>'
        records.append({'slug':p['slug']+'.html','heading':p['title'],'title':p['title']+' | Origami Penguin','description':p['description'],'nav':'blog','kind':'journal','published':p['published'],'breadcrumbs':[{'name':'Home','url':'/'},{'name':'Articles','url':'/blog'},{'name':'Note '+str(p['number'])}],'body':body,'styles':style})
    body='<section class="editorial-hero"><p class="eyebrow">52 notes from a work in progress</p><h2>Making the thing. Fixing the thing. Starting again.</h2><p>Stories and lessons from building Origami Penguin: writing books, creating educational resources, publishing, making videos, and finding a home for it all.</p><p>Read one each week or follow your curiosity. Each piece revisits a real project and the lessons that came with it.</p><p><a href="/'+posts[0]['slug']+'">Start with note 01 →</a> &nbsp; <a href="/chill-corner">Visit Chill Corner →</a></p></section>'
    body+='<div class="editorial-filters" hidden><label for="article-search">Find a note for where you are now</label><input type="search" id="article-search" placeholder="Search writing, reviews, covers, teaching…" autocomplete="off"><div class="filter-buttons" role="group" aria-label="Article topics"><button type="button" data-topic="all" aria-pressed="true">All notes</button>'+''.join('<button type="button" data-topic="'+e(c)+'" aria-pressed="false">'+e(c)+'</button>' for c in categories)+'</div><p class="editorial-status" id="article-count" role="status" aria-live="polite">52 articles</p></div><p id="article-empty" hidden>No matching notes. Try a different word or choose All notes.</p><div class="journal-grid">'
    for p in posts:
        body+=f'<article class="journal-card" data-category="{e(p["category"])}"><p class="card-kicker">Note {p["number"]:02} · {e(p["category"])}</p><h2><a href="/{p["slug"]}">{e(p["title"])}</a></h2><p>{e(p["description"])}</p><a class="read-note" href="/{p["slug"]}">Read the note <span aria-hidden="true">↗</span></a></article>'
    body+='</div><section class="origami-shelf"><h2>Still here for the folds</h2><p>The original origami articles and illustrated tutorials are staying right here.</p><ul><li><a href="/blog-folding-tips">10 tips for crisp, professional folds</a></li><li><a href="/blog-history">A brief history of origami</a></li><li><a href="/blog-best-paper">Origami paper compared</a></li><li><a href="/tutorials">Explore the illustrated folding tutorials</a></li></ul></section>'
    records.append({'slug':'blog.html','heading':'The Creative Notebook','title':'The Creative Notebook | Writing & Creator Articles | Origami Penguin','description':'52 reflections from building Origami Penguin: writing fiction, making educational resources, publishing, videos, and creative work in progress.','nav':'blog','body':body,'styles':style,'scripts':['js/journal.js'],'breadcrumbs':[{'name':'Home','url':'/'},{'name':'Articles'}]})
    groups={
        'rain':('Rain at the window','Gentle rain for a reading session, plus a storm option if you like a little thunder.'),
        'forest':('A little room to breathe','Birdsong, soft wind, and night sounds, without music.'),
        'fire':('Pull up a chair','An hour of fire crackle for a cozy background.'),
        'music':('Follow the lights','Gentle ambient music with northern lights or an evening mountain scene.'),
        'space':('Somewhere a little further away','Cosmic soundscapes for a writing session or a longer wind-down.')
    }
    mapping={'fljijxaub7M':'rain','pVIA71T0D5o':'rain','vgv1dBmSF0I':'rain','4BmoL1txFrQ':'forest','TC_cliUaayI':'forest','TRzDU2K8-jE':'forest','BAZHjUyVOVM':'fire','G_c6vAUDbVM':'music','RXRugSvgUKw':'music','lolbx0WeEI0':'space','vj4hrjfiqdI':'space','vcEVoO5IT4w':'space'}
    names={'fljijxaub7M':('Rainy window','90 minutes · Rain only','Gentle rain without thunder, music, or talking.'),'pVIA71T0D5o':('Rain for reading & study','1 hour · Rain only','Continuous rain with a warm window scene. No music or timer bells.'),'vgv1dBmSF0I':('Forest rain & distant thunder','90 minutes · Includes thunder','A deeper rain soundscape with occasional distant thunder.'),'4BmoL1txFrQ':('Morning forest','1 hour · Nature sounds','Light birdsong and a breeze through the trees. No music.'),'TC_cliUaayI':('Night forest','90 minutes · Nature sounds','Night crickets and soft wind beneath an illustrated canopy.'),'TRzDU2K8-jE':('Gentle wind in the trees','45 minutes · Nature sounds','Rustling leaves, sparse bird calls, and golden forest scenes.'),'BAZHjUyVOVM':('Crackling campfire','1 hour · Fire sounds','Warm firelight scenes and fire crackle, without music or talking.'),'G_c6vAUDbVM':('Aurora ambience','30 minutes · Ambient music','Soft tones and glass-like notes under northern-lights artwork.'),'RXRugSvgUKw':('Mountain sunset','45 minutes · Ambient music','Unhurried ambient tones against illustrated mountain ridges.'),'lolbx0WeEI0':('Deep space','2 hours · Cosmic drone','An evolving low drone and a star field that gradually dims.'),'vj4hrjfiqdI':('The long way through space','8 hours · Cosmic drone','A soft space soundscape with a dimming picture. The screen stays dim rather than fully black.'),'vcEVoO5IT4w':('Space for focus','1 hour · Ambient music','A continuous cosmic soundscape with slow star-field visuals and no talking.')}
    body='<section class="chill-hero"><p class="eyebrow">Relaxation Station · A quieter part of Origami Penguin</p><h2>Leave a little room in the day.</h2><p>Put on some rain. Sit by a fire. Let the next chapter wait a minute. These long-form videos from our Relaxation Station channel are here for reading, writing, folding, or simply taking a break.</p><p><a href="https://www.youtube.com/@relaxationstationloops" target="_blank" rel="noopener">Explore Relaxation Station on YouTube ↗</a></p></section><div class="chill-choices" aria-label="Choose a soundscape">'+''.join('<a href="#'+key+'">'+e(label)+'</a>' for key,(label,_) in groups.items())+'</div><p class="editorial-status">Choose a video below to play it here. Start any video and the next plays automatically. The collection loops so you can leave it running.</p>'
    player='<section class="chill-player" id="chill-player" aria-labelledby="chill-player-title" hidden><p class="player-eyebrow">Your listening space</p><h2 id="chill-player-title" tabindex="-1">Pick a soundscape and settle in.</h2><div class="chill-player-frame" id="chill-player-frame"><button type="button" id="chill-player-start" data-video="fljijxaub7M" data-name="Rainy window"><span class="player-play-icon" aria-hidden="true">▶</span><span>Play Rainy window</span><small>Or choose any video below</small></button></div><div class="chill-player-actions"><p id="chill-player-status" role="status" aria-live="polite">Choose a video to begin continuous listening. Pause, volume, and fullscreen are in the player; Stop ends the session.</p><button type="button" id="chill-player-stop" hidden>Stop video</button></div><a id="chill-player-external" href="https://www.youtube.com/watch?v=fljijxaub7M" target="_blank" rel="noopener">Open starting video on YouTube ↗</a></section><noscript><p>Video links open on YouTube when JavaScript is off.</p></noscript>'
    body=body.replace('</section><div class="chill-choices"','</section>'+player+'<div class="chill-choices"')
    for group,(title,intro) in groups.items():
        body+='<section class="video-group" id="'+group+'"><h2>'+e(title)+'</h2><p>'+e(intro)+'</p><div class="video-grid">'
        for v in videos:
            if mapping[v['id']]!=group:continue
            title,duration,description=names[v['id']]
            body+='<article class="video-card"><a class="chill-play" data-video="'+e(v['id'])+'" data-name="'+e(title)+'" href="'+e(v['url'])+'" target="_blank" rel="noopener" aria-label="Play '+e(title)+' here"><img src="'+e(v['image'])+'" alt="'+e(title)+' video thumbnail" width="1280" height="720" loading="lazy" decoding="async"></a><div class="video-copy"><p class="duration">'+e(duration)+'</p><h3>'+e(title)+'</h3><p>'+e(description)+'</p><a class="chill-play" data-video="'+e(v['id'])+'" data-name="'+e(title)+'" href="'+e(v['url'])+'" target="_blank" rel="noopener">Play here</a></div></article>'
        body+='</div></section>'
    body+='<aside class="quiet-note"><h2>Your pace is the right pace.</h2><p>Start at a comfortable volume and choose the sound you enjoy. These videos use designed soundscapes, original illustrated or procedural scenes, and, for the campfire, assembled stock footage.</p><p>Ready to return? <a href="/blog">Read a note from the creative notebook</a>, <a href="/books">find a story</a>, or <a href="/tutorials">make a fold</a>.</p></aside>'
    records.append({'slug':'chill-corner.html','heading':'Chill Corner','title':'Chill Corner | Relaxation Station Videos | Origami Penguin','description':'A quieter corner for rain, forest sounds, campfire ambience, ambient music, and deep-space soundscapes from Relaxation Station.','nav':'chill','body':body,'styles':style+(root/'chill-player.css').read_text(encoding='utf-8'),'scripts':['js/chill-player.js?v=2'],'breadcrumbs':[{'name':'Home','url':'/'},{'name':'Chill Corner'}]})
    return records
